WITH wave_b_payload(document) AS (
  VALUES ('{"as_of":"2026-07-29","method":"Causal exchange review using court, regulator, administrator, operator, and authoritative security records. Product scope is stated explicitly; disputed allegations and unresolved recovery outcomes remain bounded.","source_check":{"checked_at":"2026-07-29","rule":"Every published source_ref is a direct HTTPS reference reviewed for the claim it supports. A resolving page is not treated as proof of facts outside that page; disputed and inaccessible records remain qualified."},"cases":[{"table":"dead_exchanges","kind":"cex","slug":"blockfi","sources":[{"title":"BlockFi Plan FAQ","publisher":"BlockFi Official Committee","url":"https://blockfiofficialcommittee.com/faq/plan/","checked_at":"2026-07-29"},{"title":"BlockFi Final Plan","publisher":"BlockFi Official Committee","url":"https://blockfiofficialcommittee.com/downloads/BlockFi%20-%20Final%20Plan.pdf","checked_at":"2026-07-29"},{"title":"BlockFi distribution","publisher":"Coinbase","url":"https://help.coinbase.com/en/coinbase/other-topics/other/blockfi-distribution","checked_at":"2026-07-29"}],"row_patch":{"verdict":"defunct","why":"BlockFi was a custodial lender and yield platform, not primarily an exchange. Its failure followed a concentrated credit and liquidity chain: loans to Three Arrows Capital weakened the balance sheet, an FTX rescue increased dependence on one counterparty, and FTX''s collapse removed both liquidity support and recoverable asset value. BlockFi filed Chapter 11 on November 28, 2022. The plan became effective on October 24, 2023; the estate later announced that eligible allowed customer claims would receive 100% of their petition-date dollarized value, which is not the same as returning the original quantity of crypto.","outlook":"The product is wound down. Distributions continue through the bankruptcy administrator and Coinbase; recovery should be measured against allowed petition-date claim value, not current token prices."},"forensic_analysis":{"version":"forensic-analysis-v1","outcome":{"label":"failed","summary":"BlockFi is a wound-down crypto lender. Its confirmed Chapter 11 plan became effective on October 24, 2023, and the estate later enabled final distributions intended to pay eligible allowed customer and unsecured claims at 100% of petition-date dollarized claim value. That percentage does not restore foregone crypto appreciation or make every filed claim eligible.","confidence":"high","as_of":"2026-07-29","source_refs":["https://blockfiofficialcommittee.com/faq/plan/","https://help.coinbase.com/en/coinbase/other-topics/other/blockfi-distribution","https://blockfiofficialcommittee.com/"]},"why":{"summary":"BlockFi funded long-dated and concentrated crypto credit with customer liabilities that could leave quickly. Three Arrows Capital losses impaired the lender; accepting FTX''s credit facility and acquisition option then replaced one concentration with dependence on FTX. When FTX failed, BlockFi lost a liquidity backstop and filed bankruptcy. This was a lender asset-liability and counterparty-risk failure, not a blockchain outage.","confidence":"high","source_refs":["https://blockfiofficialcommittee.com/downloads/BlockFi%20-%20Final%20Plan.pdf","https://blockfiofficialcommittee.com/faq/plan/","https://www.sec.gov/newsroom/press-releases/2022-26"]},"strategic_choices":[{"decision":"Offer interest accounts and institutional loans while retaining customer custody.","consequence":"The model created yield and growth but transformed withdrawable customer claims into exposure to opaque, correlated borrowers and collateral.","confidence":"high","source_refs":["https://www.sec.gov/newsroom/press-releases/2022-26","https://blockfiofficialcommittee.com/downloads/BlockFi%20-%20Final%20Plan.pdf"]},{"decision":"Use FTX''s 2022 rescue facility after the Three Arrows Capital shock.","consequence":"The facility provided short-term liquidity while tying BlockFi''s survival and recoveries to a counterparty that failed months later.","confidence":"high","source_refs":["https://blockfiofficialcommittee.com/downloads/BlockFi%20-%20Final%20Plan.pdf"]},{"decision":"Resolve the estate through liquidation and claim sales instead of relaunching the lending product.","consequence":"Asset monetization improved dollar recoveries while permanently ending the original operating model.","confidence":"high","source_refs":["https://blockfiofficialcommittee.com/faq/plan/","https://blockfiofficialcommittee.com/"]}],"counterfactual":{"summary":"Lower single-borrower limits, independently verified collateral, matched-duration funding, and a liquidity reserve could have reduced the Three Arrows Capital loss and the need for FTX rescue financing. They would also have reduced yield and growth; the record cannot establish that such a smaller lender would have remained viable through the 2022 run.","confidence":"medium","source_refs":["https://blockfiofficialcommittee.com/downloads/BlockFi%20-%20Final%20Plan.pdf","https://www.sec.gov/newsroom/press-releases/2022-26"]},"watch":[{"signal":"Final distribution notices, disputed-claim resolutions, and unclaimed-fund deadlines.","implication":"These determine realized recoveries; a headline 100% figure cannot be applied to unresolved or ineligible claims.","source_refs":["https://blockfiofficialcommittee.com/","https://help.coinbase.com/en/coinbase/other-topics/other/blockfi-distribution"]},{"signal":"Estate reporting of remaining FTX-related proceeds and administrative costs.","implication":"Additional proceeds can improve recoveries, while prolonged administration can reduce the distributable estate.","source_refs":["https://blockfiofficialcommittee.com/faq/plan/"]}],"unknowns":["What share of filed claims will ultimately receive the advertised full petition-date dollar value after eligibility disputes and administration?","What is the claimant-level opportunity cost versus returning the original crypto quantities?","How much additional value remains in unresolved estate claims after fees?"],"review":{"status":"current","last_reviewed_at":"2026-07-29","next_review_at":"2026-08-05","reviewer":"chaindump-research-desk"}}},{"table":"dead_exchanges","kind":"cex","slug":"celsius","sources":[{"title":"Examiner''s report","publisher":"Celsius bankruptcy docket","url":"https://cases.stretto.com/public/x191/11749/PLEADINGS/1174901312380000000039.pdf","checked_at":"2026-07-29"},{"title":"Celsius claim-distribution overview","publisher":"Celsius Distribution","url":"https://celsiusdistribution.stretto.com/support/solutions/articles/153000147043-claim-distributions-overview","checked_at":"2026-07-29"},{"title":"Founder of Celsius sentenced to 12 years","publisher":"U.S. Department of Justice","url":"https://www.justice.gov/usao-sdny/pr/founder-celsius-sentenced-12-years-fraud-and-market-manipulation","checked_at":"2026-07-29"}],"row_patch":{"verdict":"defunct","why":"Celsius was a custodial lender and yield platform. It promised liquid, high-yield customer products while deploying assets into illiquid and correlated loans, DeFi positions, mining, and CEL-token support. The independent examiner documented weak controls and misleading statements; withdrawals froze in June 2022 and Chapter 11 followed on July 13. The plan became effective January 31, 2024, and the app closed in February 2024.","outlook":"The lender is closed. Bankruptcy distributions remain active, including a fourth distribution announced in February 2026; founder Alex Mashinsky was sentenced to 12 years in May 2025."},"forensic_analysis":{"version":"forensic-analysis-v1","outcome":{"label":"failed","summary":"Celsius no longer operates its lending app. Its reorganization became effective January 31, 2024, distributions remain in progress, and a fourth distribution was announced in February 2026. Founder Alex Mashinsky pleaded guilty and was sentenced to 12 years in prison on May 8, 2025.","confidence":"high","as_of":"2026-07-29","source_refs":["https://celsiusdistribution.stretto.com/support/solutions/articles/153000147043-claim-distributions-overview","https://celsiusdistribution.stretto.com/support/solutions/articles/153000252038-fourth-distribution","https://www.justice.gov/usao-sdny/pr/founder-celsius-sentenced-12-years-fraud-and-market-manipulation"]},"why":{"summary":"Celsius paired callable customer liabilities with risky, illiquid, and correlated asset deployments while representing the business as safer and more liquid than it was. The examiner documented inadequate risk systems, balance-sheet holes, and use of customer assets for CEL purchases. Market stress exposed the mismatch; the run was the trigger, not the sole cause.","confidence":"high","source_refs":["https://cases.stretto.com/public/x191/11749/PLEADINGS/1174901312380000000039.pdf","https://www.ftc.gov/system/files/ftc_gov/pdf/2223137celsiusnetworkcomplaint.pdf","https://www.justice.gov/usao-sdny/pr/founder-celsius-sentenced-12-years-fraud-and-market-manipulation"]},"strategic_choices":[{"decision":"Market high-yield, readily withdrawable accounts while retaining broad discretion over customer-asset deployment.","consequence":"Growth and assets increased, but customer liquidity promises were unsupported by an equally liquid asset base.","confidence":"high","source_refs":["https://cases.stretto.com/public/x191/11749/PLEADINGS/1174901312380000000039.pdf","https://www.ftc.gov/system/files/ftc_gov/pdf/2223137celsiusnetworkcomplaint.pdf"]},{"decision":"Use customer deposits to purchase CEL and emphasize token economics.","consequence":"Celsius increased exposure to its own confidence-sensitive token and obscured the separation between product economics and token-price support.","confidence":"high","source_refs":["https://cases.stretto.com/public/x191/11749/PLEADINGS/1174901312380000000039.pdf","https://www.justice.gov/usao-sdny/pr/founder-celsius-sentenced-12-years-fraud-and-market-manipulation"]},{"decision":"Expand into mining, DeFi, and institutional credit without commensurate accounting and risk controls.","consequence":"Operational complexity and correlated exposure made the true liquidity position harder to measure and unwind during stress.","confidence":"high","source_refs":["https://cases.stretto.com/public/x191/11749/PLEADINGS/1174901312380000000039.pdf"]}],"counterfactual":{"summary":"Segregated custody, conservative collateral and duration limits, audited reserves, and no customer-funded CEL support would have reduced run severity and misleading token dependence. Those controls likely would have forced lower yields and slower growth; whether a compliant lower-yield product could have competed is unknown.","confidence":"medium","source_refs":["https://cases.stretto.com/public/x191/11749/PLEADINGS/1174901312380000000039.pdf","https://www.ftc.gov/system/files/ftc_gov/pdf/2223137celsiusnetworkcomplaint.pdf"]},"watch":[{"signal":"Distribution rounds, claim-resolution notices, and recovery percentages by claim class.","implication":"Realized recovery varies by eligibility, claim class, and distribution rail rather than a single platform-wide percentage.","source_refs":["https://celsiusdistribution.stretto.com/support/solutions/articles/153000147043-claim-distributions-overview","https://celsiusdistribution.stretto.com/support/solutions/articles/153000252038-fourth-distribution"]},{"signal":"Estate litigation proceeds and remaining wind-down expenses.","implication":"Net recoveries can improve from successful litigation but decline with delay and administration costs.","source_refs":["https://celsiusdistribution.stretto.com/support/solutions/articles/153000147043-claim-distributions-overview"]}],"unknowns":["What final recovery will each claim class realize after all litigation and administrative expenses?","How much customer value was lost through foregone crypto appreciation versus nominal claim impairment?","Which controls would regulators require before a comparable yield product could operate sustainably?"],"review":{"status":"current","last_reviewed_at":"2026-07-29","next_review_at":"2026-08-05","reviewer":"chaindump-research-desk"}}},{"table":"dead_exchanges","kind":"cex","slug":"coinflex","sources":[{"title":"Liquidity Technologies Ltd v. Lamb case record","publisher":"LawHero / Hong Kong Judiciary record","url":"https://lawhero.io/cases/17330/hca1646-2023-liquidity-technologies-ltd-and-another-v-mark-david-lamb-and-others","checked_at":"2026-07-29"},{"title":"CoinFLEX identifies disputed counterparty claim","publisher":"CNBC","url":"https://www.cnbc.com/2022/06/29/crypto-exchange-coinflex-claims-roger-ver-is-behind-47-million-debt.html","checked_at":"2026-07-29"},{"title":"OPNX to shut down","publisher":"The Block","url":"https://www.theblock.co/post/275695/crypto-derivatives-exchange-opnx-to-shut-down-in-february","checked_at":"2026-07-29"}],"row_patch":{"verdict":"defunct","why":"CoinFLEX was a centralized derivatives exchange that granted a special manual-margin arrangement to a large counterparty. It halted withdrawals on June 23, 2022 after that account produced a deficit. CoinFLEX publicly identified Roger Ver and pursued an $84 million claim; the allegation was disputed and should not be treated as an adjudicated debt here. Seychelles approved a creditor restructuring in March 2023, after which personnel and assets were associated with OPNX; OPNX closed in February 2024.","outlook":"CoinFLEX is not an operating exchange. Creditor value depended on equity and recovery tokens tied to disputed litigation, while the successor OPNX venue also shut down."},"forensic_analysis":{"version":"forensic-analysis-v1","outcome":{"label":"failed","summary":"CoinFLEX ceased as a standalone exchange after a counterparty-driven withdrawal halt and court-approved restructuring. Creditors received restructured interests including equity and recovery-linked tokens; OPNX, the later venue associated with CoinFLEX assets and personnel, closed in February 2024.","confidence":"high","as_of":"2026-07-29","source_refs":["https://lawhero.io/cases/17330/hca1646-2023-liquidity-technologies-ltd-and-another-v-mark-david-lamb-and-others","https://www.theblock.co/post/275695/crypto-derivatives-exchange-opnx-to-shut-down-in-february"]},"why":{"summary":"The immediate deficit came from a concentrated counterparty position that CoinFLEX did not automatically liquidate under a special manual-margin agreement. The strategic failure was granting exception-based credit and allowing one account to create a platform-wide liquidity hole. The named counterparty and amount remain attributed claims; the court record confirms CoinFLEX''s restructuring position, not this analysis independently resolving the dispute.","confidence":"high","source_refs":["https://lawhero.io/cases/17330/hca1646-2023-liquidity-technologies-ltd-and-another-v-mark-david-lamb-and-others","https://www.cnbc.com/2022/06/29/crypto-exchange-coinflex-claims-roger-ver-is-behind-47-million-debt.html"]},"strategic_choices":[{"decision":"Permit a large counterparty to operate under a manual-margin arrangement rather than ordinary automatic liquidation.","consequence":"One disputed default generated an exchange-wide deficit and withdrawal suspension, socializing concentrated credit risk across customers.","confidence":"high","source_refs":["https://lawhero.io/cases/17330/hca1646-2023-liquidity-technologies-ltd-and-another-v-mark-david-lamb-and-others"]},{"decision":"Convert creditor impairment into equity and litigation-contingent recovery tokens.","consequence":"The scheme preserved claims on possible future value but did not create liquid cash recovery independent of litigation or successor execution.","confidence":"high","source_refs":["https://lawhero.io/cases/17330/hca1646-2023-liquidity-technologies-ltd-and-another-v-mark-david-lamb-and-others"]},{"decision":"Associate CoinFLEX assets and personnel with the OPNX claims venue.","consequence":"The pivot attempted to reuse technology and distribution, but OPNX''s closure removed the operating-growth thesis for creditor equity.","confidence":"medium","source_refs":["https://www.theblock.co/post/218171/coinflex-rebrands-to-opnx-with-leslie-lamb-as-ceo-of-3ac-founders-latest-venture","https://www.theblock.co/post/275695/crypto-derivatives-exchange-opnx-to-shut-down-in-february"]}],"counterfactual":{"summary":"Enforcing automatic liquidation, hard counterparty limits, and pre-funded loss reserves would likely have contained the default. CoinFLEX would have sacrificed VIP volume and fees, but customer withdrawals would have been less dependent on one bilateral promise.","confidence":"high","source_refs":["https://lawhero.io/cases/17330/hca1646-2023-liquidity-technologies-ltd-and-another-v-mark-david-lamb-and-others"]},"watch":[{"signal":"Final disposition and collections from CoinFLEX''s disputed counterparty claims.","implication":"Recovery-token value depends on realized collections, not the face value asserted by CoinFLEX.","source_refs":["https://lawhero.io/cases/17330/hca1646-2023-liquidity-technologies-ltd-and-another-v-mark-david-lamb-and-others"]},{"signal":"Liquidator or scheme reporting on creditor cash, equity, and token recoveries.","implication":"Audited realized distributions are needed to distinguish nominal restructuring consideration from economic recovery.","source_refs":["https://lawhero.io/cases/17330/hca1646-2023-liquidity-technologies-ltd-and-another-v-mark-david-lamb-and-others"]}],"unknowns":["What amount, if any, was finally adjudicated and collected from the disputed counterparty?","What cash-equivalent recovery did each creditor class realize from equity and recovery tokens?","How much customer exposure remained after OPNX closed?"],"review":{"status":"current","last_reviewed_at":"2026-07-29","next_review_at":"2026-08-05","reviewer":"chaindump-research-desk"}}},{"table":"dead_exchanges","kind":"cex","slug":"fcoin","sources":[{"title":"FCoin expects to default on user bitcoin","publisher":"The Block","url":"https://www.theblock.co/post/56191/cryptocurrency-exchange-fcoin-expects-to-default-on-as-much-as-125m-of-users-bitcoin","checked_at":"2026-07-29"},{"title":"FCoin''s transaction-fee-mining model","publisher":"CoinDesk","url":"https://www.coindesk.com/markets/2018/06/22/fcoin-crypto-exchange-draws-fire-for-controversial-business-model","checked_at":"2026-07-29"},{"title":"FCoin describes transaction-fee mining","publisher":"FCoin press release","url":"https://www.prnewswire.com/news-releases/trans-fee-mining-model-fcoin-the-chinese-cryptocurrency-exchange-is-leading-the-industry-300699262.html","checked_at":"2026-07-29"}],"row_patch":{"verdict":"defunct","why":"FCoin stopped processing withdrawals in February 2020 after founder Zhang Jian said the exchange could not repay an estimated 7,000-13,000 BTC. He attributed the shortfall to data and decision errors rather than a hack. FCoin''s transaction-fee-mining design refunded trading fees in FT tokens and shared most fee revenue with token holders, encouraging reflexive volume while creating complex token and accounting liabilities. No court finding establishes an exit scam.","outlook":"FCoin remains offline with no verified comprehensive recovery, adjudication, or operating successor. The founder''s current status and final creditor recoveries are not established by authoritative records reviewed."},"forensic_analysis":{"version":"forensic-analysis-v1","outcome":{"label":"failed","summary":"FCoin is defunct. Its founder announced in February 2020 that the exchange could not meet an estimated 7,000-13,000 BTC of withdrawal obligations. No verified comprehensive repayment or relaunch was identified, and allegations of an exit scam remain allegations rather than a legal finding.","confidence":"medium","as_of":"2026-07-29","source_refs":["https://www.theblock.co/post/56191/cryptocurrency-exchange-fcoin-expects-to-default-on-as-much-as-125m-of-users-bitcoin","https://www.coindesk.com/markets/2018/06/22/fcoin-crypto-exchange-draws-fire-for-controversial-business-model"]},"why":{"summary":"FCoin coupled exchange trading with transaction-fee mining: users received FT tokens against fees, while token holders were promised a large share of fee revenue. The mechanism attracted volume but made apparent activity, token issuance, and liabilities reflexive. The founder said accounting and decision errors accumulated into an unpayable gap. Available records do not establish whether misconduct, insolvency, or both explain every missing asset.","confidence":"medium","source_refs":["https://www.theblock.co/post/56191/cryptocurrency-exchange-fcoin-expects-to-default-on-as-much-as-125m-of-users-bitcoin","https://www.coindesk.com/markets/2018/06/22/fcoin-crypto-exchange-draws-fire-for-controversial-business-model","https://www.prnewswire.com/news-releases/trans-fee-mining-model-fcoin-the-chinese-cryptocurrency-exchange-is-leading-the-industry-300699262.html"]},"strategic_choices":[{"decision":"Refund trading fees with newly issued FT tokens and distribute most exchange fee revenue to token holders.","consequence":"The structure rapidly attracted activity but rewarded churn, linked reported success to token issuance, and complicated liability accounting.","confidence":"high","source_refs":["https://www.prnewswire.com/news-releases/trans-fee-mining-model-fcoin-the-chinese-cryptocurrency-exchange-is-leading-the-industry-300699262.html","https://www.coindesk.com/markets/2018/06/22/fcoin-crypto-exchange-draws-fire-for-controversial-business-model"]},{"decision":"Scale the incentive model before proving resilient reconciliation, custody, and reserve controls.","consequence":"According to the founder, data errors and operational decisions compounded until recorded user balances exceeded repayable assets.","confidence":"medium","source_refs":["https://www.theblock.co/post/56191/cryptocurrency-exchange-fcoin-expects-to-default-on-as-much-as-125m-of-users-bitcoin"]},{"decision":"Center governance and remediation on founder assurances after the shutdown.","consequence":"Without an independent administrator or public audited reserve process, users lacked a verifiable recovery mechanism.","confidence":"medium","source_refs":["https://www.theblock.co/post/56191/cryptocurrency-exchange-fcoin-expects-to-default-on-as-much-as-125m-of-users-bitcoin"]}],"counterfactual":{"summary":"Capping token rebates, excluding self-trading, reconciling liabilities daily, and publishing independent custody attestations could have reduced reflexive volume and exposed the gap earlier. Those controls would probably have reduced FCoin''s headline growth, which was itself the product''s primary distribution advantage.","confidence":"medium","source_refs":["https://www.coindesk.com/markets/2018/06/22/fcoin-crypto-exchange-draws-fire-for-controversial-business-model","https://www.theblock.co/post/56191/cryptocurrency-exchange-fcoin-expects-to-default-on-as-much-as-125m-of-users-bitcoin"]},"watch":[{"signal":"Authoritative court, regulator, or administrator records identifying recoveries or legal disposition.","implication":"Such records could upgrade the low-visibility outcome and resolve whether any repayment occurred.","source_refs":["https://www.theblock.co/post/56191/cryptocurrency-exchange-fcoin-expects-to-default-on-as-much-as-125m-of-users-bitcoin"]},{"signal":"Comparable exchange incentives that reimburse fees with a venue-issued token.","implication":"Volume should be discounted unless wash-trading controls, liability reconciliation, and external reserves are verifiable.","source_refs":["https://www.coindesk.com/markets/2018/06/22/fcoin-crypto-exchange-draws-fire-for-controversial-business-model"]}],"unknowns":["How much of FCoin''s volume represented organic demand versus incentive cycling or wash activity?","What assets, if any, were ultimately distributed to customers?","Was the shortfall caused solely by the founder-described accounting failures, or did unproven misconduct also contribute?"],"review":{"status":"current","last_reviewed_at":"2026-07-29","next_review_at":"2026-10-29","reviewer":"chaindump-research-desk"}}},{"table":"dead_exchanges","kind":"cex","slug":"genesis-global","sources":[{"title":"Genesis completes restructuring and begins distributions","publisher":"Genesis","url":"https://www.businesswire.com/news/home/20240802215732/en/Genesis-Completes-Restructuring-and-Commences-Distributions-to-Creditors","checked_at":"2026-07-29"},{"title":"Genesis settlement and victims fund","publisher":"New York Attorney General","url":"https://ag.ny.gov/index.php/press-release/2024/attorney-general-james-secures-settlement-worth-2-billion-crypto-firm-genesis","checked_at":"2026-07-29"},{"title":"Genesis confirmation opinion","publisher":"U.S. Bankruptcy Court, Southern District of New York","url":"https://www.nysb.uscourts.gov/sites/default/files/opinions/314889_2140_opinion.pdf","checked_at":"2026-07-29"}],"row_patch":{"verdict":"defunct","why":"Genesis Global Capital and related lending debtors—not the separately regulated Genesis Global Trading spot dealer—failed after concentrated unsecured credit losses to Three Arrows Capital and exposure to FTX/Alameda, compounded by Digital Currency Group intercompany complexity. The lending debtors filed Chapter 11 in January 2023. Their plan became effective August 2, 2024 and commenced roughly $4 billion of distributions.","outlook":"The lending businesses are in wind-down. Initial average recovery was reported at about 64% in-kind across creditors, with class-specific outcomes; New York''s up-to-$2 billion victims fund is part of the residual recovery structure, not an additional completed $2 billion distribution."},"forensic_analysis":{"version":"forensic-analysis-v1","outcome":{"label":"failed","summary":"Genesis''s lending debtors completed restructuring and began about $4 billion of creditor distributions on August 2, 2024, with an approximately 64% average initial in-kind recovery that varied by asset and claim class. New York''s settlement created an up-to-$2 billion subordinated victims fund; it should not be added to the initial distribution as though $6 billion had already been paid.","confidence":"high","as_of":"2026-07-29","source_refs":["https://www.businesswire.com/news/home/20240802215732/en/Genesis-Completes-Restructuring-and-Commences-Distributions-to-Creditors","https://ag.ny.gov/index.php/press-release/2024/attorney-general-james-secures-settlement-worth-2-billion-crypto-firm-genesis","https://www.nysb.uscourts.gov/sites/default/files/opinions/314889_2140_opinion.pdf"]},"why":{"summary":"Genesis Global Capital''s institutional lending model concentrated credit in highly correlated crypto borrowers. Three Arrows Capital''s default created a large hole, and FTX/Alameda''s failure later froze liquidity and confidence. DCG support and intercompany claims delayed recognition rather than removing the risk. This causal account applies to the lending debtors; Genesis Global Trading separately surrendered its New York BitLicense after DFS compliance findings.","confidence":"high","source_refs":["https://www.nysb.uscourts.gov/sites/default/files/opinions/314889_2140_opinion.pdf","https://www.businesswire.com/news/home/20240802215732/en/Genesis-Completes-Restructuring-and-Commences-Distributions-to-Creditors","https://www.dfs.ny.gov/reports_and_publications/press_releases/pr2024011224"]},"strategic_choices":[{"decision":"Concentrate institutional crypto credit in large correlated counterparties, including Three Arrows Capital.","consequence":"A single major default produced a balance-sheet impairment that parent support did not economically erase.","confidence":"high","source_refs":["https://www.nysb.uscourts.gov/sites/default/files/opinions/314889_2140_opinion.pdf"]},{"decision":"Use affiliated-company support and claims within the DCG group after losses emerged.","consequence":"The structure deferred immediate failure but created valuation, priority, and governance disputes in the bankruptcy.","confidence":"high","source_refs":["https://www.nysb.uscourts.gov/sites/default/files/opinions/314889_2140_opinion.pdf","https://ag.ny.gov/index.php/press-release/2024/attorney-general-james-secures-settlement-worth-2-billion-crypto-firm-genesis"]},{"decision":"Operate lending, trading, and affiliated distribution relationships under the broader Genesis/DCG brand.","consequence":"Customers and public reporting frequently conflated legally distinct entities, obscuring which balance sheet, regulator, and recovery process applied.","confidence":"high","source_refs":["https://www.dfs.ny.gov/reports_and_publications/press_releases/pr2024011224","https://www.businesswire.com/news/home/20240802215732/en/Genesis-Completes-Restructuring-and-Commences-Distributions-to-Creditors"]}],"counterfactual":{"summary":"Hard single-name and correlated-sector limits, transparent affiliate exposures, and term-matched liquidity would have reduced the Three Arrows Capital and FTX transmission channels. Those controls would have constrained the scale and pricing advantage of Genesis''s institutional lending franchise but likely preserved more optionality.","confidence":"medium","source_refs":["https://www.nysb.uscourts.gov/sites/default/files/opinions/314889_2140_opinion.pdf","https://ag.ny.gov/index.php/press-release/2024/attorney-general-james-secures-settlement-worth-2-billion-crypto-firm-genesis"]},"watch":[{"signal":"Residual estate distributions, class-level recoveries, and proceeds allocated through the New York victims fund.","implication":"These data determine final claimant recovery and prevent double-counting nominal settlement caps.","source_refs":["https://ag.ny.gov/index.php/press-release/2024/attorney-general-james-secures-settlement-worth-2-billion-crypto-firm-genesis","https://www.businesswire.com/news/home/20240802215732/en/Genesis-Completes-Restructuring-and-Commences-Distributions-to-Creditors"]},{"signal":"Resolution of DCG and affiliate claims and remaining litigation expenses.","implication":"Net estate value depends on realized affiliate recoveries after legal and administrative costs.","source_refs":["https://www.nysb.uscourts.gov/sites/default/files/opinions/314889_2140_opinion.pdf"]}],"unknowns":["What final recovery will each asset and creditor class receive after residual distributions?","How much of the up-to-$2 billion New York fund will ultimately be funded and distributed?","What portion of losses is attributable to initial underwriting versus later affiliate restructuring decisions?"],"review":{"status":"current","last_reviewed_at":"2026-07-29","next_review_at":"2026-08-05","reviewer":"chaindump-research-desk"}}},{"table":"dead_exchanges","kind":"cex","slug":"hodlnaut","sources":[{"title":"Hodlnaut liquidation","publisher":"EY Singapore","url":"https://www.ey.com/en_sg/hodlnaut-pte-ltd","checked_at":"2026-07-29"},{"title":"Fifty-first liquidator circular","publisher":"EY Singapore","url":"https://www.ey.com/content/dam/ey-unified-site/ey-com/en-sg/campaigns/hodlnaut-pte-ltd/documents/ey-sg-l051-fifty-first-circular-27-02-2026.pdf","checked_at":"2026-07-29"},{"title":"Former Hodlnaut CEO charged","publisher":"Singapore Police Force","url":"https://www.police.gov.sg/Media-Hub/News/2026/05/20260526_former_chief_executive_officer_of_hodlnaut_charged_for_fraud_by_false_representation","checked_at":"2026-07-29"}],"row_patch":{"verdict":"defunct","why":"Hodlnaut was a custodial crypto lender, not an exchange. It halted withdrawals in August 2022 after concentrated TerraUSD/Anchor exposure and other losses impaired liquidity. Singapore police allege former CEO Zhu Juntao directed misleading statements about UST exposure; six fraud-by-false-representation charges filed in May 2026 remain pending and are not convictions.","outlook":"The company has been in liquidation since November 10, 2023. EY''s February 27, 2026 circular said proofs of debt and a first interim dividend were still being prepared for more than 17,000 potential creditors."},"forensic_analysis":{"version":"forensic-analysis-v1","outcome":{"label":"failed","summary":"Hodlnaut is in court-ordered liquidation. As of the liquidators'' February 27, 2026 circular, more than 17,000 potential creditor claims remained in scope and the first interim dividend was not yet ready for distribution. Former CEO Zhu Juntao faces six pending fraud-by-false-representation charges concerning alleged UST-exposure statements.","confidence":"high","as_of":"2026-07-29","source_refs":["https://www.ey.com/en_sg/hodlnaut-pte-ltd","https://www.ey.com/content/dam/ey-unified-site/ey-com/en-sg/campaigns/hodlnaut-pte-ltd/documents/ey-sg-l051-fifty-first-circular-27-02-2026.pdf","https://www.police.gov.sg/Media-Hub/News/2026/05/20260526_former_chief_executive_officer_of_hodlnaut_charged_for_fraud_by_false_representation"]},"why":{"summary":"Hodlnaut promised yield and liquid withdrawals while deploying customer assets into concentrated, correlated crypto positions, including UST/Anchor. The Terra collapse crystallized losses and a run exposed the liquidity mismatch. Police allegations that management misrepresented direct UST exposure, if proved, would explain why users could not price the risk; the criminal case remains unresolved.","confidence":"high","source_refs":["https://www.police.gov.sg/Media-Hub/News/2026/05/20260526_former_chief_executive_officer_of_hodlnaut_charged_for_fraud_by_false_representation","https://www.police.gov.sg/media-hub/news/2022/20221123_inv_into_hodlnaut_pte_ltd","https://www.elitigation.sg/gd/s/2022_SGHC_209"]},"strategic_choices":[{"decision":"Deploy customer assets into UST/Anchor while offering a generalized yield account.","consequence":"A protocol and stablecoin failure became a platform solvency event rather than an isolated investment loss.","confidence":"high","source_refs":["https://www.police.gov.sg/Media-Hub/News/2026/05/20260526_former_chief_executive_officer_of_hodlnaut_charged_for_fraud_by_false_representation","https://www.elitigation.sg/gd/s/2022_SGHC_209"]},{"decision":"Communicate limited or no direct UST exposure during market stress, according to pending police allegations.","consequence":"If proved, those statements delayed informed customer response and damaged trust; the charges have not been adjudicated.","confidence":"medium","source_refs":["https://www.police.gov.sg/Media-Hub/News/2026/05/20260526_former_chief_executive_officer_of_hodlnaut_charged_for_fraud_by_false_representation"]},{"decision":"Seek judicial management before liquidation.","consequence":"The process preserved time to assess restructuring, but creditors ultimately rejected the path and liquidation began after additional delay.","confidence":"high","source_refs":["https://www.ey.com/en_sg/hodlnaut-pte-ltd","https://www.elitigation.sg/gd/s/2022_SGHC_209"]}],"counterfactual":{"summary":"Hard protocol and stablecoin concentration limits, segregated custody, transparent exposure reporting, and liquid reserves could have contained Terra losses and reduced the run. Those controls would have lowered achievable yield and revealed that the product was risk-bearing lending rather than cash-like savings.","confidence":"high","source_refs":["https://www.police.gov.sg/Media-Hub/News/2026/05/20260526_former_chief_executive_officer_of_hodlnaut_charged_for_fraud_by_false_representation","https://www.elitigation.sg/gd/s/2022_SGHC_209"]},"watch":[{"signal":"EY proof-of-debt determinations and first interim dividend notice.","implication":"These will convert gross claims into verified claim counts and realized recovery.","source_refs":["https://www.ey.com/content/dam/ey-unified-site/ey-com/en-sg/campaigns/hodlnaut-pte-ltd/documents/ey-sg-l051-fifty-first-circular-27-02-2026.pdf"]},{"signal":"Judicial disposition of the six charges against Zhu Juntao.","implication":"A conviction, acquittal, or withdrawal would materially change confidence in the alleged disclosure failure.","source_refs":["https://www.police.gov.sg/Media-Hub/News/2026/05/20260526_former_chief_executive_officer_of_hodlnaut_charged_for_fraud_by_false_representation"]}],"unknowns":["What verified creditor recovery percentage will the liquidators distribute?","What portion of the loss came from UST/Anchor versus other trading, counterparty, and custody exposures?","How will the pending criminal charges be resolved?"],"review":{"status":"current","last_reviewed_at":"2026-07-29","next_review_at":"2026-08-05","reviewer":"chaindump-research-desk"}}},{"table":"dead_exchanges","kind":"cex","slug":"prime-trust","sources":[{"title":"Petition to place Prime Trust in receivership","publisher":"Nevada Financial Institutions Division","url":"https://fid.nv.gov/uploadedFiles/fidnvgov/content/Resources/Nevada%20Financial%20Institutions%20Files%20Court%20Petition%20to%20Place%20Prime%20Trust%2C%20LLC%20in%20Receivership.pdf","checked_at":"2026-07-29"},{"title":"Prime Trust confirmation order","publisher":"U.S. Bankruptcy Court / Prime Trust Wind Down","url":"https://primetrustwinddown.com/wp-content/uploads/2024/01/confirmation-order.pdf","checked_at":"2026-07-29"}],"row_patch":{"verdict":"defunct","why":"Prime Trust was a Nevada-chartered crypto custodian and B2B payment infrastructure provider, not a retail exchange. Nevada regulators alleged that after losing access to legacy wallets, Prime used customer omnibus funds from December 2021 through March 2022 to buy replacement crypto for withdrawals. The June 2023 receivership petition reported an $82.8 million fiat deficit, an $861,000 digital-asset deficit, and negative equity.","outlook":"Prime Trust''s Chapter 11 liquidation plan became effective January 5, 2024. The business is winding down through trust and bankruptcy processes, with class-specific distributions rather than a relaunch."},"forensic_analysis":{"version":"forensic-analysis-v1","outcome":{"label":"failed","summary":"Prime Trust is a liquidating custodian. Nevada''s receivership petition reported that it owed about $85.7 million in fiat while holding about $2.9 million, plus a smaller digital-asset deficit. Its Chapter 11 plan was confirmed December 21, 2023 and became effective January 5, 2024.","confidence":"high","as_of":"2026-07-29","source_refs":["https://fid.nv.gov/uploadedFiles/fidnvgov/content/Resources/Nevada%20Financial%20Institutions%20Files%20Court%20Petition%20to%20Place%20Prime%20Trust%2C%20LLC%20in%20Receivership.pdf","https://primetrustwinddown.com/wp-content/uploads/2024/01/confirmation-order.pdf"]},"why":{"summary":"Prime Trust lost access to legacy wallets, then used customer omnibus money to repurchase crypto needed for customer withdrawals, according to Nevada''s petition. That operational key-management failure became a balance-sheet and custody-control failure. Expansion spending and weak governance further depleted capital. The official filing reviewed does not support describing Terra investment or FTX linkage as the primary cause.","confidence":"high","source_refs":["https://fid.nv.gov/uploadedFiles/fidnvgov/content/Resources/Nevada%20Financial%20Institutions%20Files%20Court%20Petition%20to%20Place%20Prime%20Trust%2C%20LLC%20in%20Receivership.pdf","https://primetrustwinddown.com/wp-content/uploads/2024/01/confirmation-order.pdf"]},"strategic_choices":[{"decision":"Maintain customer obligations after losing access to legacy-wallet assets by purchasing replacement crypto with omnibus funds.","consequence":"A key-management incident was transferred into a customer-fund deficit instead of being recognized and recapitalized immediately.","confidence":"high","source_refs":["https://fid.nv.gov/uploadedFiles/fidnvgov/content/Resources/Nevada%20Financial%20Institutions%20Files%20Court%20Petition%20to%20Place%20Prime%20Trust%2C%20LLC%20in%20Receivership.pdf"]},{"decision":"Expand product and infrastructure spending while the balance sheet and custody controls were impaired.","consequence":"Cash burn reduced the firm''s capacity to repair the deficit and increased dependence on outside financing.","confidence":"high","source_refs":["https://fid.nv.gov/uploadedFiles/fidnvgov/content/Resources/Nevada%20Financial%20Institutions%20Files%20Court%20Petition%20to%20Place%20Prime%20Trust%2C%20LLC%20in%20Receivership.pdf"]},{"decision":"Resolve the failure through a liquidating Chapter 11 plan.","consequence":"The plan enabled ordered claim treatment but ended Prime Trust''s value proposition as a trusted custody intermediary.","confidence":"high","source_refs":["https://primetrustwinddown.com/wp-content/uploads/2024/01/confirmation-order.pdf"]}],"counterfactual":{"summary":"Independent key recovery, wallet reconciliation, segregated customer accounts, daily liability matching, and immediate loss recognition could have contained the legacy-wallet incident. If inaccessible assets could not be recovered, only prompt recapitalization or an orderly stop—not customer-funded replacement purchases—could preserve custody integrity.","confidence":"high","source_refs":["https://fid.nv.gov/uploadedFiles/fidnvgov/content/Resources/Nevada%20Financial%20Institutions%20Files%20Court%20Petition%20to%20Place%20Prime%20Trust%2C%20LLC%20in%20Receivership.pdf"]},"watch":[{"signal":"Wind-down trustee reports and distributions by convenience, general unsecured, and customer claim classes.","implication":"Class-level cash recovery is the meaningful outcome; scheduled percentages for one class cannot be generalized to all customers.","source_refs":["https://primetrustwinddown.com/wp-content/uploads/2024/01/confirmation-order.pdf"]},{"signal":"Any final regulatory or judicial findings on custody losses and responsible parties.","implication":"Final findings may refine the causal allocation beyond the allegations in the receivership petition.","source_refs":["https://fid.nv.gov/uploadedFiles/fidnvgov/content/Resources/Nevada%20Financial%20Institutions%20Files%20Court%20Petition%20to%20Place%20Prime%20Trust%2C%20LLC%20in%20Receivership.pdf"]}],"unknowns":["What final recovery will each customer and unsecured claim class realize?","How much inaccessible legacy-wallet value was ever recovered?","Which control failures were ultimately attributed to individuals or vendors by final adjudication?"],"review":{"status":"current","last_reviewed_at":"2026-07-29","next_review_at":"2026-08-05","reviewer":"chaindump-research-desk"}}},{"table":"dead_exchanges","kind":"cex","slug":"thodex","sources":[{"title":"Thodex appellate judgment report","publisher":"Anadolu Agency","url":"https://www.aa.com.tr/tr/gundem/istinaf-thodexin-kurucusu-faruk-fatih-ozerin-dolandiricilik-davasinda-kararini-verdi/3467025","checked_at":"2026-07-29"},{"title":"Justice Ministry statement on Faruk Fatih Özer''s death","publisher":"Republic of Türkiye Ministry of Justice","url":"https://cte.adalet.gov.tr/Home/SayfaDetay/hukumozlu-faruk-fatih-ozerin-intihari-ile-ilgili-iddialara-iliskin-basin-aciklamasi02112025081301","checked_at":"2026-07-29"}],"row_patch":{"verdict":"defunct","why":"Thodex stopped withdrawals in April 2021 and founder Faruk Fatih Özer fled Turkey. Prosecutors and MASAK records reported hundreds of millions of Turkish lira in losses and transfers, but viral claims of $2-2.6 billion and 400,000 defrauded users are not used here as verified loss totals. A trial court imposed an 11,196-year sentence in 2023; an appellate court partly vacated and remanded the judgment in January 2025 while detention continued on other offenses.","outlook":"The exchange is permanently defunct. Turkey''s Justice Ministry reported that Özer died by suicide in prison on November 1, 2025; remaining proceedings and customer recovery require case-specific court records."},"forensic_analysis":{"version":"forensic-analysis-v1","outcome":{"label":"dead","summary":"Thodex is defunct. The 2023 trial judgment was not the final procedural endpoint: an Istanbul appellate court partly vacated and remanded major portions in January 2025. Founder Faruk Fatih Özer died in prison on November 1, 2025, according to Turkey''s Justice Ministry.","confidence":"high","as_of":"2026-07-29","source_refs":["https://www.aa.com.tr/tr/gundem/istinaf-thodexin-kurucusu-faruk-fatih-ozerin-dolandiricilik-davasinda-kararini-verdi/3467025","https://cte.adalet.gov.tr/Home/SayfaDetay/hukumozlu-faruk-fatih-ozerin-intihari-ile-ilgili-iddialara-iliskin-basin-aciklamasi02112025081301"]},"why":{"summary":"Thodex combined centralized custody with founder control and inadequate barriers against moving customer-linked assets out of the venue. Withdrawal suspension and the founder''s flight converted an opaque custody system into a total trust failure. Court reporting supports fraud and asset-transfer allegations, but the appellate remand means individual counts and sentences must be stated with procedural qualification.","confidence":"high","source_refs":["https://www.aa.com.tr/tr/gundem/istinaf-thodexin-kurucusu-faruk-fatih-ozerin-dolandiricilik-davasinda-kararini-verdi/3467025"]},"strategic_choices":[{"decision":"Centralize custody and operational authority without transparent reserves or independent withdrawal controls.","consequence":"Customers could not verify backing or prevent insiders from suspending access and moving assets.","confidence":"high","source_refs":["https://www.aa.com.tr/tr/gundem/istinaf-thodexin-kurucusu-faruk-fatih-ozerin-dolandiricilik-davasinda-kararini-verdi/3467025"]},{"decision":"Use promotions and rapid retail acquisition without matching public governance and solvency disclosure.","consequence":"Growth increased the number of dependent users while leaving risk concentrated in an opaque operator.","confidence":"medium","source_refs":["https://www.aa.com.tr/tr/gundem/istinaf-thodexin-kurucusu-faruk-fatih-ozerin-dolandiricilik-davasinda-kararini-verdi/3467025"]},{"decision":"Suspend the venue and leave the jurisdiction instead of conducting an independently supervised wind-down.","consequence":"The failure shifted recovery to criminal and asset-tracing processes with long delays and uncertain claimant outcomes.","confidence":"high","source_refs":["https://www.aa.com.tr/tr/gundem/istinaf-thodexin-kurucusu-faruk-fatih-ozerin-dolandiricilik-davasinda-kararini-verdi/3467025"]}],"counterfactual":{"summary":"Segregated custody, independent withdrawal approvals, reserve attestations, and regulator-visible beneficial ownership could have constrained insider action or exposed deficits earlier. These controls cannot prove the business would have remained solvent, but they would have reduced the single-founder failure mode.","confidence":"medium","source_refs":["https://www.aa.com.tr/tr/gundem/istinaf-thodexin-kurucusu-faruk-fatih-ozerin-dolandiricilik-davasinda-kararini-verdi/3467025"]},"watch":[{"signal":"Final appellate and remand judgments for remaining defendants and offenses.","implication":"Only final dispositions can replace the current qualified description of convictions and sentences.","source_refs":["https://www.aa.com.tr/tr/gundem/istinaf-thodexin-kurucusu-faruk-fatih-ozerin-dolandiricilik-davasinda-kararini-verdi/3467025"]},{"signal":"Official asset-recovery and victim-distribution records.","implication":"Verified distributions are needed before assigning a customer recovery percentage or defensible dollar loss.","source_refs":["https://www.aa.com.tr/tr/gundem/istinaf-thodexin-kurucusu-faruk-fatih-ozerin-dolandiricilik-davasinda-kararini-verdi/3467025"]}],"unknowns":["What final loss amount and verified victim count will courts recognize?","What assets have actually been returned to customers?","How will the founder''s death affect remanded proceedings, confiscation, and claims against other defendants?"],"review":{"status":"current","last_reviewed_at":"2026-07-29","next_review_at":"2026-08-05","reviewer":"chaindump-research-desk"}}},{"table":"dead_exchanges","kind":"cex","slug":"vauld","sources":[{"title":"Vauld restructuring FAQ","publisher":"Vauld","url":"https://support.vauld.com/en/articles/6382973-faqs-on-vauld-group-restructuring-as-of-31-july-22","checked_at":"2026-07-29"},{"title":"Vauld scheme effective date","publisher":"Vauld","url":"https://support.vauld.com/en/articles/8262950-corporate-announcement-scheme-effective-date-16-aug-2023","checked_at":"2026-07-29"},{"title":"Vauld second distribution FAQ","publisher":"Vauld","url":"https://support.vauld.com/en/articles/13557945-second-distribution-faqs-dt-29-jan-2026","checked_at":"2026-07-29"}],"row_patch":{"verdict":"defunct","why":"Vauld was a custodial lender and yield platform, not primarily an exchange. It halted withdrawals on July 4, 2022 after a run exposed losses, counterparty concentration, and an asset-liability mismatch. Singapore sanctioned its creditor scheme in August 2023. The scheme is a managed wind-down, not a return of the original product.","outlook":"Distributions continue under the scheme. Vauld''s January 2026 FAQ described an $82.3 million second distribution and class-specific cumulative recovery at effective-date rebalancing prices; withdrawals were temporarily suspended in June 2025 for regulatory registration work."},"forensic_analysis":{"version":"forensic-analysis-v1","outcome":{"label":"failed","summary":"Vauld remains a wind-down estate under a Singapore-sanctioned scheme effective August 16, 2023. Its January 2026 second-distribution FAQ described $82.3 million for distribution and cumulative recovery of 25% for PRT creditors and 29% for VRT creditors at effective-date rebalancing prices, not a product relaunch.","confidence":"high","as_of":"2026-07-29","source_refs":["https://support.vauld.com/en/articles/8262950-corporate-announcement-scheme-effective-date-16-aug-2023","https://support.vauld.com/en/articles/13557945-second-distribution-faqs-dt-29-jan-2026","https://support.vauld.com/en/articles/11768488-important-update-temporary-suspension-of-withdrawals-from-30-june-2025"]},"why":{"summary":"Vauld offered liquid customer withdrawals against loans and deployed assets whose value and availability deteriorated during the 2022 credit crisis. The Celsius freeze helped trigger a run, but Vauld''s own counterparty, market, and liquidity choices made the run fatal. The record supports a lender asset-liability failure rather than describing contagion as an unavoidable external event.","confidence":"high","source_refs":["https://support.vauld.com/en/articles/6382973-faqs-on-vauld-group-restructuring-as-of-31-july-22","https://support.vauld.com/en/articles/6655404-creditors-committee-meeting-updates-and-q-as-as-of-20-oct-22","https://support.vauld.com/en/articles/8262910-scheme-related-faqs-as-of-16-aug-2023"]},"strategic_choices":[{"decision":"Offer high-yield, readily withdrawable accounts while deploying assets through lending and trading counterparties.","consequence":"Customer liabilities remained liquid while recoverable assets became impaired or delayed during correlated market stress.","confidence":"high","source_refs":["https://support.vauld.com/en/articles/6382973-faqs-on-vauld-group-restructuring-as-of-31-july-22","https://support.vauld.com/en/articles/6655404-creditors-committee-meeting-updates-and-q-as-as-of-20-oct-22"]},{"decision":"Seek a creditor scheme with fixed wind-down terms rather than continue pursuing an operating rescue.","consequence":"The scheme created a distribution process but locked creditors into time, pricing, and recovery-class tradeoffs.","confidence":"high","source_refs":["https://support.vauld.com/en/articles/8262950-corporate-announcement-scheme-effective-date-16-aug-2023","https://support.vauld.com/en/articles/8262910-scheme-related-faqs-as-of-16-aug-2023"]},{"decision":"Use effective-date rebalancing prices and separate PRT/VRT recovery tracks.","consequence":"The structure standardizes distributions but makes headline percentages sensitive to claim class and reference price rather than current token value.","confidence":"high","source_refs":["https://support.vauld.com/en/articles/13557945-second-distribution-faqs-dt-29-jan-2026"]}],"counterfactual":{"summary":"Matched-duration funding, tighter counterparty limits, liquid reserves, and transparent deployment disclosures could have reduced the run''s impact. The likely tradeoff was lower advertised yield and slower asset growth; the evidence cannot show that an acquisition or recapitalization would have succeeded even with those controls.","confidence":"medium","source_refs":["https://support.vauld.com/en/articles/6382973-faqs-on-vauld-group-restructuring-as-of-31-july-22","https://support.vauld.com/en/articles/6655404-creditors-committee-meeting-updates-and-q-as-as-of-20-oct-22"]},"watch":[{"signal":"Scheme distributions, regulatory withdrawal access, and recovery by PRT/VRT class.","implication":"Realized class-level recovery and access matter more than nominal estate value.","source_refs":["https://support.vauld.com/en/articles/13557945-second-distribution-faqs-dt-29-jan-2026","https://support.vauld.com/en/articles/11768488-important-update-temporary-suspension-of-withdrawals-from-30-june-2025"]},{"signal":"Resolution of remaining counterparty assets and extension or completion of the scheme term.","implication":"Collections can improve distributions; delay and administrative cost can reduce them.","source_refs":["https://support.vauld.com/en/articles/8262910-scheme-related-faqs-as-of-16-aug-2023"]}],"unknowns":["What final recovery will each creditor class realize at current market value?","How much remains recoverable from unresolved counterparties?","Will regulatory restrictions cause material additional distribution delay?"],"review":{"status":"current","last_reviewed_at":"2026-07-29","next_review_at":"2026-08-05","reviewer":"chaindump-research-desk"}}},{"table":"dead_exchanges","kind":"cex","slug":"voyager-digital","sources":[{"title":"Voyager first-day declaration","publisher":"Voyager bankruptcy docket","url":"https://www.afslaw.com/sites/default/files/2022-12/%5BDkt.%2015%5D%20Voyager%20First%20Day%20Declaration%20-%20CEO%20Stephen%20Ehrlich.pdf","checked_at":"2026-07-29"},{"title":"FTC Voyager settlement","publisher":"U.S. Federal Trade Commission","url":"https://www.ftc.gov/news-events/news/press-releases/2023/10/ftc-reaches-settlement-crypto-company-voyager-digital-charges-former-executive-falsely-claiming","checked_at":"2026-07-29"},{"title":"Voyager plan administrator sixth status report","publisher":"Voyager Plan Administrator","url":"https://support.investvoyager.com/hc/en-us/articles/24692429286171-Plan-Administrator-s-Sixth-Status-Report-April-9-2024","checked_at":"2026-07-29"}],"row_patch":{"verdict":"defunct","why":"Voyager was a custodial crypto broker and lender, not a conventional exchange. It extended an under-collateralized loan of 15,250 BTC and 350 million USDC to Three Arrows Capital. That concentrated exposure defaulted, Voyager filed Chapter 11 on July 5, 2022, and planned sales to FTX and then Binance.US failed. The FTC permanently banned the corporate entities from handling consumer assets.","outlook":"Voyager is in liquidation. Customers received an initial 35.72% distribution and a second distribution process, while remaining estate litigation and claims continue; no relaunch is permitted for the corporate entities covered by the FTC order."},"forensic_analysis":{"version":"forensic-analysis-v1","outcome":{"label":"failed","summary":"Voyager is a liquidating broker-lender. Its plan produced an initial 35.72% distribution and a later second distribution process, while the corporate entities accepted a permanent FTC ban on handling consumer assets. Remaining recoveries depend on estate claims and litigation, not an operating restart.","confidence":"high","as_of":"2026-07-29","source_refs":["https://www.ftc.gov/news-events/news/press-releases/2023/10/ftc-reaches-settlement-crypto-company-voyager-digital-charges-former-executive-falsely-claiming","https://support.investvoyager.com/hc/en-us/articles/28007576100507-I-don-t-see-a-Second-Distribution-check-in-my-account-Why","https://support.investvoyager.com/hc/en-us/articles/24692429286171-Plan-Administrator-s-Sixth-Status-Report-April-9-2024"]},"why":{"summary":"Voyager promised customers access to a diversified brokerage while taking concentrated institutional credit risk behind the interface. Its 3AC loan—15,250 BTC and 350 million USDC—was large enough that one borrower default drove insolvency. Failed FTX and Binance.US sale attempts prolonged resolution but were consequences of the original balance-sheet concentration, not its cause.","confidence":"high","source_refs":["https://www.afslaw.com/sites/default/files/2022-12/%5BDkt.%2015%5D%20Voyager%20First%20Day%20Declaration%20-%20CEO%20Stephen%20Ehrlich.pdf","https://www.ftc.gov/news-events/news/press-releases/2023/10/ftc-reaches-settlement-crypto-company-voyager-digital-charges-former-executive-falsely-claiming"]},"strategic_choices":[{"decision":"Fund a very large under-collateralized exposure to Three Arrows Capital.","consequence":"A single counterparty default overwhelmed Voyager''s capital and converted brokerage customers into bankruptcy creditors.","confidence":"high","source_refs":["https://www.afslaw.com/sites/default/files/2022-12/%5BDkt.%2015%5D%20Voyager%20First%20Day%20Declaration%20-%20CEO%20Stephen%20Ehrlich.pdf"]},{"decision":"Market the customer product as safe and protected while commingling brokerage access with lending risk.","consequence":"Customers could not readily distinguish custodial balances from credit-dependent assets; the FTC alleged deceptive protection claims.","confidence":"high","source_refs":["https://www.ftc.gov/news-events/news/press-releases/2023/10/ftc-reaches-settlement-crypto-company-voyager-digital-charges-former-executive-falsely-claiming"]},{"decision":"Pursue sales to FTX and Binance.US before settling on liquidation.","consequence":"Each failed transaction delayed a stable recovery path and exposed creditors to buyer, regulatory, and market execution risk.","confidence":"high","source_refs":["https://support.investvoyager.com/hc/en-us/articles/24692429286171-Plan-Administrator-s-Sixth-Status-Report-April-9-2024"]}],"counterfactual":{"summary":"Enforced counterparty caps, independent collateral verification, segregated customer custody, and accurate protection disclosures could have reduced both insolvency severity and customer surprise. These constraints would have reduced interest income and likely changed Voyager''s growth economics.","confidence":"high","source_refs":["https://www.afslaw.com/sites/default/files/2022-12/%5BDkt.%2015%5D%20Voyager%20First%20Day%20Declaration%20-%20CEO%20Stephen%20Ehrlich.pdf","https://www.ftc.gov/news-events/news/press-releases/2023/10/ftc-reaches-settlement-crypto-company-voyager-digital-charges-former-executive-falsely-claiming"]},"watch":[{"signal":"Plan-administrator status reports and any further creditor distributions.","implication":"Only paid distributions establish final recovery; announced estate assets are not equivalent to claimant cash.","source_refs":["https://support.investvoyager.com/hc/en-us/articles/28007576100507-I-don-t-see-a-Second-Distribution-check-in-my-account-Why","https://support.investvoyager.com/hc/en-us/articles/24692429286171-Plan-Administrator-s-Sixth-Status-Report-April-9-2024"]},{"signal":"Remaining litigation recoveries and claim objections.","implication":"Successful collections can raise final recovery, while fees and adverse judgments reduce it.","source_refs":["https://support.investvoyager.com/hc/en-us/articles/24692429286171-Plan-Administrator-s-Sixth-Status-Report-April-9-2024"]}],"unknowns":["What final aggregate percentage will customers receive after all distributions?","How much value was lost relative to returning the original crypto rather than dollarized claims?","What net amount will remaining litigation contribute after fees?"],"review":{"status":"current","last_reviewed_at":"2026-07-29","next_review_at":"2026-08-05","reviewer":"chaindump-research-desk"}}},{"table":"mid_exchanges","kind":"cex","slug":"wazirx","sources":[{"title":"Preliminary report on the WazirX multisig attack","publisher":"WazirX","url":"https://wazirx.com/blog/preliminary-report-cyber-attack-on-wazirx-multisig-wallet/","checked_at":"2026-07-29"},{"title":"Liminal response to the WazirX incident","publisher":"Liminal Custody","url":"https://www.liminalcustody.com/blog/liminal-remains-secure-amidst-sophisticated-attack/","checked_at":"2026-07-29"},{"title":"WazirX scheme effective","publisher":"WazirX","url":"https://wazirx.com/blog/the-scheme-of-arrangement-is-now-effective/","checked_at":"2026-07-29"}],"row_patch":{"verdict":"recovering","why":"WazirX lost more than $230 million from a multisignature wallet on July 18, 2024. WazirX and custody provider Liminal published conflicting accounts of the control failure, so the record does not conclusively assign the breach to one party. A Singapore scheme became effective October 15, 2025; trading restarted October 24, and the first distribution was approximately 85% of approved claims at scheme reference prices.","outlook":"WazirX is operating again but recovery remains partial and scheme-dependent. Recovery tokens represent contingent rights to future recoveries and platform value, not guaranteed payment of the remaining 15%."},"forensic_analysis":{"version":"forensic-analysis-v1","outcome":{"label":"recovering","summary":"WazirX resumed trading on October 24, 2025 after its restructuring scheme became effective. The first distribution represented approximately 85% of approved claims at scheme reference prices, and recovery tokens were allocated in January 2026 for contingent future value. Operations have restarted, but customer recovery and trust are incomplete.","confidence":"high","as_of":"2026-07-29","source_refs":["https://wazirx.com/blog/the-scheme-of-arrangement-is-now-effective/","https://wazirx.com/blog/wazirx-comeback-journey-2025/","https://wazirx.com/blog/recovery-tokens-explained/"]},"why":{"summary":"A multisignature custody workflow failed under a sophisticated attack, allowing more than $230 million to leave one wallet. WazirX describes three hardware-wallet approvals plus a Liminal approval; Liminal disputes responsibility and describes a customer-side compromise. Regardless of attribution, concentrating a large share of assets in one operational signing path made a single control-plane incident systemically damaging.","confidence":"high","source_refs":["https://wazirx.com/blog/preliminary-report-cyber-attack-on-wazirx-multisig-wallet/","https://www.liminalcustody.com/blog/liminal-remains-secure-amidst-sophisticated-attack/","https://wazirx.com/blog/wazirx-cyber-attack-key-insights-and-learnings/"]},"strategic_choices":[{"decision":"Concentrate substantial exchange assets in a multisignature workflow shared with a third-party custody interface.","consequence":"The design required several approvals but still exposed a large asset pool to one coordinated signing and interface failure.","confidence":"high","source_refs":["https://wazirx.com/blog/preliminary-report-cyber-attack-on-wazirx-multisig-wallet/","https://www.liminalcustody.com/blog/liminal-remains-secure-amidst-sophisticated-attack/"]},{"decision":"Use a court-sanctioned pro-rata scheme instead of making unaffected assets immediately withdrawable in full.","consequence":"Losses were distributed across approved claims, enabling a restart but imposing collective impairment and pricing-date risk.","confidence":"high","source_refs":["https://wazirx.com/blog/the-scheme-of-arrangement-is-now-effective/","https://wazirx.com/blog/wazirx-comeback-journey-2025/"]},{"decision":"Issue recovery tokens for the residual claim.","consequence":"Users retain contingent upside from future recoveries, but token allocation is not cash, liquid market value, or guaranteed repayment.","confidence":"high","source_refs":["https://wazirx.com/blog/recovery-tokens-explained/"]}],"counterfactual":{"summary":"Smaller hot-wallet limits, independent transaction-intent verification, signer separation across devices and networks, and tested incident circuit breakers could have reduced loss severity. No multisig threshold alone proves security when signers share the same compromised transaction context.","confidence":"high","source_refs":["https://wazirx.com/blog/preliminary-report-cyber-attack-on-wazirx-multisig-wallet/","https://www.liminalcustody.com/blog/liminal-remains-secure-amidst-sophisticated-attack/","https://wazirx.com/blog/wazirx-cyber-attack-key-insights-and-learnings/"]},"watch":[{"signal":"Realized recovery-token distributions, asset recoveries, and scheme reporting.","implication":"These determine whether the residual 15% claim acquires economic value beyond a contingent token.","source_refs":["https://wazirx.com/blog/recovery-tokens-explained/","https://wazirx.com/blog/wazirx-comeback-journey-2025/"]},{"signal":"Post-restart withdrawal reliability, reserves, custody architecture, and verified trading activity.","implication":"Sustained withdrawals and independently verifiable custody would support recovery; renewed restrictions would reverse it.","source_refs":["https://wazirx.com/blog/wazirx-comeback-journey-2025/","https://wazirx.com/blog/wazirx-cyber-attack-key-insights-and-learnings/"]}],"unknowns":["Which control plane was compromised, and how will any final independent or judicial finding allocate responsibility?","What cash or token value will recovery-token holders ultimately realize?","What share of post-restart volume and reserves is independently verifiable?"],"review":{"status":"current","last_reviewed_at":"2026-07-29","next_review_at":"2026-08-05","reviewer":"chaindump-research-desk"}}},{"table":"mid_exchanges","kind":"cex","slug":"xeggex","sources":[{"title":"XeggeX terms and identified product surface","publisher":"XeggeX","url":"https://xeggex.com/legal/terms","checked_at":"2026-07-29"},{"title":"XeggeX news surface","publisher":"XeggeX","url":"https://xeggex.com/news","checked_at":"2026-07-29"},{"title":"XeggeX operator incident channel","publisher":"XeggeX","url":"https://t.me/s/xeggex?before=128","checked_at":"2026-07-29"}],"row_patch":{"verdict":"unresolved","why":"XeggeX reported a February 2025 security incident and loss of systems and data after compromise of a primary administrator''s device. Public evidence reviewed does not substantiate the existing claims of a June 27, 2025 bankruptcy, an $80 million loss, 12,000 affected users, or a legal finding that funds were unrecoverable. A website now responds with market and login pages, but that does not prove custody restoration, solvency, withdrawals, or continuity with the former operator.","outlook":"Operational and creditor status remain unresolved. Treat the current web surface as an unverified signal, not evidence of a successful relaunch; do not publish a loss total or bankruptcy status without a regulator, court, or identified legal-entity record."},"forensic_analysis":{"version":"forensic-analysis-v1","outcome":{"label":"unclassified","summary":"XeggeX''s post-incident status is unresolved. Its current website exposes login, market, and legal pages but no reviewed authoritative record proves customer restitution, reserve sufficiency, or continuous operation. Earlier claims of bankruptcy, an $80 million loss, and 12,000 affected users are withheld for lack of verified primary support.","confidence":"low","as_of":"2026-07-29","source_refs":["https://xeggex.com/legal/terms","https://xeggex.com/news","https://t.me/s/xeggex?before=128"]},"why":{"summary":"The operator''s incident communications described compromise of a primary administrator device with access across systems and loss of data. That points to excessive administrative blast radius and inadequate independent recovery paths. Because the available first-party account is incomplete and no reviewed regulator or court finding resolves the incident, loss amount, custody outcome, and operator continuity remain unknown.","confidence":"low","source_refs":["https://t.me/s/xeggex?before=128","https://xeggex.com/legal/terms"]},"strategic_choices":[{"decision":"Concentrate broad systems access around a primary administrator endpoint, according to the operator''s incident account.","consequence":"One endpoint compromise allegedly crossed application, infrastructure, and data boundaries instead of remaining contained.","confidence":"low","source_refs":["https://t.me/s/xeggex?before=128"]},{"decision":"Rely on public social-channel updates without publishing an identified legal entity, audited incident report, or claimant process.","consequence":"Users and researchers cannot verify liabilities, recovery, responsible operator, or the legal status of customer claims.","confidence":"medium","source_refs":["https://t.me/s/xeggex?before=128","https://xeggex.com/legal/terms"]},{"decision":"Restore a public web surface without prominently publishing custody, reserve, or restitution evidence.","consequence":"Site availability may attract users while leaving the material question—whether deposits and withdrawals are solvent and continuous—unanswered.","confidence":"medium","source_refs":["https://xeggex.com/news","https://xeggex.com/legal/terms"]}],"counterfactual":{"summary":"Hardware-backed least-privilege administration, separated production roles, immutable offline backups, and an independently audited incident-and-restitution process would have reduced blast radius and improved verifiability. The incomplete public record prevents estimating how much loss those controls would have avoided.","confidence":"medium","source_refs":["https://t.me/s/xeggex?before=128","https://xeggex.com/legal/terms"]},"watch":[{"signal":"An identified operating legal entity, regulator record, audited reserves, and independently tested deposits and withdrawals.","implication":"Together these could support reclassification as operating; a live website alone cannot.","source_refs":["https://xeggex.com/legal/terms","https://xeggex.com/news"]},{"signal":"A court, liquidator, law-enforcement, or independent incident report quantifying claims and asset recovery.","implication":"Authoritative records would permit a supported loss total and outcome classification.","source_refs":["https://t.me/s/xeggex?before=128"]}],"unknowns":["Who is the current legal operator and is it the same entity that held pre-incident customer assets?","What assets and customer records were lost, recovered, or distributed?","Are deposits, withdrawals, reported markets, and reserves independently verifiable?"],"review":{"status":"current","last_reviewed_at":"2026-07-29","next_review_at":"2026-08-05","reviewer":"chaindump-research-desk"}}},{"table":"dead_exchanges","kind":"cex","slug":"zipmex","sources":[{"title":"Zipmex moratorium judgment","publisher":"Singapore High Court","url":"https://littdb.sfo2.cdn.digitaloceanspaces.com/litt/SG/SLW/pdfs/_2024__SGHC_6.pdf","checked_at":"2026-07-29"},{"title":"Revocation of Zipmex exchange and broker licenses","publisher":"Thailand Securities and Exchange Commission","url":"https://www.sec.or.th/TH/Pages/News_Detail.aspx?SECID=10843","checked_at":"2026-07-29"},{"title":"Zipmex confirms Babel and Celsius exposure","publisher":"CoinDesk","url":"https://www.coindesk.com/markets/2022/07/21/zipmex-confirms-loans-worth-53m-to-babel-and-celsius","checked_at":"2026-07-29"}],"row_patch":{"verdict":"defunct","why":"Zipmex combined a centralized exchange with the ZipUp+ yield product, transferring customer-linked assets to lending counterparties. Zipmex disclosed approximately $48 million with Babel Finance and $5 million with Celsius—not Three Arrows Capital. When those assets became unavailable, withdrawals paused. Singapore''s High Court found in January 2024 that restructuring had no remaining reasonable prospect; Thailand revoked the local exchange and broker licenses effective May 28, 2024.","outlook":"The relevant licensed Thai exchange operation is defunct. Singapore''s High Court expected liquidation after finding no restructuring prospect, but ultimate status and recovery remain entity-specific. Thai criminal complaints concerning asset transfers are allegations under investigation, not convictions."},"forensic_analysis":{"version":"forensic-analysis-v1","outcome":{"label":"failed","summary":"Zipmex''s restructuring failed and its licensed Thai exchange and broker permissions were revoked effective May 28, 2024. Singapore''s High Court found no reasonable prospect of a successful restructuring in January 2024 and expected liquidation to follow. Final status and customer recovery remain entity- and product-specific.","confidence":"high","as_of":"2026-07-29","source_refs":["https://littdb.sfo2.cdn.digitaloceanspaces.com/litt/SG/SLW/pdfs/_2024__SGHC_6.pdf","https://www.sec.or.th/TH/Pages/News_Detail.aspx?SECID=10843","https://www.sec.or.th/Documents/News/Attach/10850/FAQ%20Revocation%20of%20Zipmex%20s%20Digital%20Asset%20Exchange%20and%20Broker%20Licenses.pdf"]},"why":{"summary":"Zipmex blurred exchange custody with an off-platform yield product and concentrated approximately $53 million with Babel Finance and Celsius. When both lenders suspended access, the yield product''s credit risk became a withdrawal and confidence crisis across the brand. Failed rescue financing and fragmented group entities then prevented a durable restructuring.","confidence":"high","source_refs":["https://updates.zipmex.co.th/?lang=th&p=181635","https://www.coindesk.com/markets/2022/07/21/zipmex-confirms-loans-worth-53m-to-babel-and-celsius","https://littdb.sfo2.cdn.digitaloceanspaces.com/litt/SG/SLW/pdfs/_2024__SGHC_6.pdf"]},"strategic_choices":[{"decision":"Attach the ZipUp+ yield product to an exchange brand and transfer assets to Babel Finance and Celsius.","consequence":"Counterparty credit risk entered a product users could perceive as adjacent to ordinary exchange custody; lender freezes impaired withdrawals.","confidence":"high","source_refs":["https://updates.zipmex.co.th/?lang=th&p=181635","https://www.coindesk.com/markets/2022/07/21/zipmex-confirms-loans-worth-53m-to-babel-and-celsius"]},{"decision":"Pursue repeated rescue and restructuring proposals dependent on external investment.","consequence":"Missed funding and expiring moratoria consumed time without restoring a viable balance sheet or licensed operation.","confidence":"high","source_refs":["https://littdb.sfo2.cdn.digitaloceanspaces.com/litt/SG/SLW/pdfs/_2024__SGHC_6.pdf"]},{"decision":"Operate through multiple national entities and product terms.","consequence":"Customer rights, custody location, regulatory remedies, and liquidation outcomes differed by entity and whether users accepted new terms.","confidence":"high","source_refs":["https://www.sec.or.th/Documents/News/Attach/10850/FAQ%20Revocation%20of%20Zipmex%20s%20Digital%20Asset%20Exchange%20and%20Broker%20Licenses.pdf","https://littdb.sfo2.cdn.digitaloceanspaces.com/litt/SG/SLW/pdfs/_2024__SGHC_6.pdf"]}],"counterfactual":{"summary":"Keeping exchange custody segregated from yield lending, publishing counterparty exposures, and limiting any one lender could have contained Babel and Celsius losses to a clearly risk-labeled product. A pre-funded wind-down plan could also have reduced dependence on rescue investors after the freeze.","confidence":"high","source_refs":["https://updates.zipmex.co.th/?lang=th&p=181635","https://www.sec.or.th/Documents/News/Attach/10850/FAQ%20Revocation%20of%20Zipmex%20s%20Digital%20Asset%20Exchange%20and%20Broker%20Licenses.pdf"]},"watch":[{"signal":"Liquidator notices and customer distributions by Zipmex entity and wallet/product classification.","implication":"Group-level recovery claims can mislead unless mapped to the legal entity and terms governing each customer.","source_refs":["https://littdb.sfo2.cdn.digitaloceanspaces.com/litt/SG/SLW/pdfs/_2024__SGHC_6.pdf","https://www.sec.or.th/Documents/News/Attach/10850/FAQ%20Revocation%20of%20Zipmex%20s%20Digital%20Asset%20Exchange%20and%20Broker%20Licenses.pdf"]},{"signal":"Thai investigative and judicial disposition of alleged asset transfers.","implication":"Only a final disposition can convert regulator-reported complaints into findings of responsibility.","source_refs":["https://www.sec.or.th/Documents/News/Attach/10850/FAQ%20Revocation%20of%20Zipmex%20s%20Digital%20Asset%20Exchange%20and%20Broker%20Licenses.pdf"]}],"unknowns":["What final recovery will each entity and product cohort receive?","What amount remains recoverable from Babel Finance and other counterparties?","How will Thai investigations and cross-border liquidation priorities be resolved?"],"review":{"status":"current","last_reviewed_at":"2026-07-29","next_review_at":"2026-08-05","reviewer":"chaindump-research-desk"}}}]}')
)
INSERT OR REPLACE INTO exchange_cex_causal_wave_b_0060 (
  target_table,
  kind,
  slug,
  analysis,
  verdict,
  why,
  outlook,
  sources
)
SELECT
  json_extract(value, '$.table'),
  json_extract(value, '$.kind'),
  json_extract(value, '$.slug'),
  json_extract(value, '$.forensic_analysis'),
  json_extract(value, '$.row_patch.verdict'),
  json_extract(value, '$.row_patch.why'),
  json_extract(value, '$.row_patch.outlook'),
  json_extract(value, '$.sources')
FROM wave_b_payload, json_each(wave_b_payload.document, '$.cases');
-- canonical-payload-end

INSERT OR REPLACE INTO mid_exchanges (
  slug,
  kind,
  venue_type,
  name,
  launched,
  metric_label,
  metric_type,
  metric_unit,
  metric,
  verdict,
  why_stuck,
  outlook,
  profile,
  sources,
  updated_at
)
SELECT
  dead.slug,
  dead.kind,
  dead.venue_type,
  dead.name,
  dead.launched,
  dead.metric_label,
  dead.metric_type,
  dead.metric_unit,
  dead.current_metric,
  wave.verdict,
  wave.why,
  wave.outlook,
  json_set(
    COALESCE(NULLIF(dead.profile, ''), '{}'),
    '$.forensic_analysis',
    json(wave.analysis)
  ),
  json(wave.sources),
  '2026-07-29'
FROM dead_exchanges AS dead
JOIN exchange_cex_causal_wave_b_0060 AS wave
  ON wave.target_table = 'mid_exchanges'
 AND wave.kind = dead.kind
 AND wave.slug = dead.slug;

UPDATE exchange_case_features
SET lifecycle = 'mid',
    last_verified_at = '2026-07-29',
    updated_at = '2026-07-29'
WHERE kind = 'cex'
  AND lifecycle = 'dead'
  AND slug IN (
    SELECT slug
    FROM exchange_cex_causal_wave_b_0060
    WHERE target_table = 'mid_exchanges'
  );

DELETE FROM dead_exchanges
WHERE kind = 'cex'
  AND slug IN (
    SELECT slug
    FROM exchange_cex_causal_wave_b_0060
    WHERE target_table = 'mid_exchanges'
  );

UPDATE dead_exchanges
SET profile = json_set(
      COALESCE(NULLIF(profile, ''), '{}'),
      '$.forensic_analysis',
      json((
        SELECT analysis
        FROM exchange_cex_causal_wave_b_0060 AS wave
        WHERE wave.target_table = 'dead_exchanges'
          AND wave.kind = dead_exchanges.kind
          AND wave.slug = dead_exchanges.slug
      ))
    ),
    verdict = (
      SELECT verdict
      FROM exchange_cex_causal_wave_b_0060 AS wave
      WHERE wave.target_table = 'dead_exchanges'
        AND wave.kind = dead_exchanges.kind
        AND wave.slug = dead_exchanges.slug
    ),
    why = (
      SELECT why
      FROM exchange_cex_causal_wave_b_0060 AS wave
      WHERE wave.target_table = 'dead_exchanges'
        AND wave.kind = dead_exchanges.kind
        AND wave.slug = dead_exchanges.slug
    ),
    outlook = (
      SELECT outlook
      FROM exchange_cex_causal_wave_b_0060 AS wave
      WHERE wave.target_table = 'dead_exchanges'
        AND wave.kind = dead_exchanges.kind
        AND wave.slug = dead_exchanges.slug
    ),
    sources = json((
      SELECT sources
      FROM exchange_cex_causal_wave_b_0060 AS wave
      WHERE wave.target_table = 'dead_exchanges'
        AND wave.kind = dead_exchanges.kind
        AND wave.slug = dead_exchanges.slug
    )),
    updated_at = '2026-07-29'
WHERE EXISTS (
  SELECT 1
  FROM exchange_cex_causal_wave_b_0060 AS wave
  WHERE wave.target_table = 'dead_exchanges'
    AND wave.kind = dead_exchanges.kind
    AND wave.slug = dead_exchanges.slug
);

DROP TABLE IF EXISTS exchange_cex_causal_wave_b_0060;
